function voicePackKey(msg){return /clear|victory|horizon/i.test(msg)?'clear':/boss|form|target|pattern|worthy|technique/i.test(msg)?'boss':/recover|guard|pressure|fall|slowing|swarm/i.test(msg)?'danger':'start'}
